package com.pulsepay.capture;
import com.pulsepay.common.ApiException; import com.pulsepay.idempotency.IdempotencyService; import com.pulsepay.ledger.LedgerService; import com.pulsepay.security.MerchantPrincipal; import java.util.*; import org.springframework.http.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/payment-intents") public class CaptureController { private final JdbcTemplate db; private final LedgerService ledger; private final IdempotencyService idempotency; public CaptureController(JdbcTemplate db,LedgerService ledger,IdempotencyService idempotency){this.db=db;this.ledger=ledger;this.idempotency=idempotency;} record Capture(long amountMinor){} @PostMapping("/{id}/capture") @ResponseStatus(HttpStatus.CREATED) @Transactional public Map<String,Object> capture(@AuthenticationPrincipal MerchantPrincipal p,@PathVariable String id,@RequestHeader(value="Idempotency-Key",required=false)String key,@RequestBody Capture r){var replay=idempotency.replayOrClaim(p.merchantId(),"payment_intent.capture:"+id,key,r);if(replay.isPresent())return replay.get();var x=db.query("select pi.id,pi.amount_minor,pi.currency,a.id,a.authorized_minor,a.captured_minor,a.status from payment_intents pi join authorizations a on a.payment_intent_id=pi.id where pi.merchant_id=? and pi.public_id=? for update",(rs,i)->new Object[]{UUID.fromString(rs.getString(1)),rs.getLong(2),rs.getString(3),UUID.fromString(rs.getString(4)),rs.getLong(5),rs.getLong(6),rs.getString(7)},p.merchantId(),id);if(x.isEmpty())throw new ApiException(HttpStatus.NOT_FOUND,"AUTHORIZATION_NOT_FOUND","Authorized payment was not found.");Object[] a=x.getFirst();long amount=r.amountMinor()<=0?(Long)a[4]:r.amountMinor();if(!Set.of("AUTHORIZED","PARTIALLY_CAPTURED").contains(a[6])||amount+(Long)a[5]>(Long)a[4])throw new ApiException(HttpStatus.CONFLICT,"INVALID_CAPTURE_AMOUNT","Capture exceeds the remaining authorized amount.");UUID cap=UUID.randomUUID();try{db.update("insert into captures(id,authorization_id,amount_minor,idempotency_key,status)values(?,?,?,?, 'SUCCEEDED')",cap,a[3],amount,key);}catch(Exception e){throw new ApiException(HttpStatus.CONFLICT,"DUPLICATE_CAPTURE","Capture request has already been processed.");}long total=amount+(Long)a[5];db.update("update authorizations set captured_minor=?,status=?,updated_at=now(),version=version+1 where id=?",total,total==(Long)a[4]?"CAPTURED":"PARTIALLY_CAPTURED",a[3]);ledger.postPayment(p.merchantId(),(UUID)a[0],amount,(String)a[2]);Map<String,Object> out=Map.of("capture_id",cap,"amount_minor",amount,"status","SUCCEEDED");idempotency.complete(p.merchantId(),"payment_intent.capture:"+id,key,out);audit(p,"payment.captured",cap);return out;} @PostMapping("/{id}/cancel-authorization") @Transactional public Map<String,Object> cancelAuthorization(@AuthenticationPrincipal MerchantPrincipal p,@PathVariable String id){var rows=db.query("select a.id,a.captured_minor,a.status from authorizations a join payment_intents pi on pi.id=a.payment_intent_id where pi.merchant_id=? and pi.public_id=? for update",(rs,i)->new Object[]{UUID.fromString(rs.getString(1)),rs.getLong(2),rs.getString(3)},p.merchantId(),id);if(rows.isEmpty())throw new ApiException(HttpStatus.NOT_FOUND,"AUTHORIZATION_NOT_FOUND","Authorized payment was not found.");Object[] authorization=rows.getFirst();if(!"AUTHORIZED".equals(authorization[2])||(Long)authorization[1]!=0)throw new ApiException(HttpStatus.CONFLICT,"INVALID_AUTHORIZATION_STATE","Only an uncaptured authorization can be cancelled.");db.update("update authorizations set status='CANCELED',updated_at=now(),version=version+1 where id=?",authorization[0]);audit(p,"authorization.canceled",(UUID)authorization[0]);return Map.of("payment_intent_id",id,"authorization_status","CANCELED");} private void audit(MerchantPrincipal p,String action,UUID id){db.update("insert into audit_logs(merchant_id,actor_user_id,action,resource_type,resource_id)values(?,?,?,'capture',?)",p.merchantId(),p.userId(),action,id);} }
